import { type ECharts, type EChartsOption, graphic, init } from "echarts";
import { createSignal, onCleanup, onMount } from "solid-js";
import Card from "../componnets/card";

export default function BulkCommoditySales() {
	let chartRef: HTMLDivElement | undefined;
	let chartInstance: ECharts | null = null;

	// 使用 createSignal 如果需要响应式更新 option
	const [option] = createSignal<EChartsOption>({
		title: {
			text: "亿元",
			left: "5%",
			top: "8%",
			textStyle: {
				color: "#D3F8F2",
				fontSize: 8,
			},
		},
		grid: {
			left: "12%",
			top: "25%",
			width: "82%",
			height: "55%",
		},
		tooltip: {
			trigger: "axis",
			axisPointer: {
				type: "shadow",
				shadowStyle: { opacity: 0 },
			},
			backgroundColor: "rgba(0,0,0,1)",
			borderWidth: 1,
			borderColor: "#ffffff",
			textStyle: {
				color: "#ffffff",
				fontSize: 10,
			},
		},
		xAxis: [
			{
				type: "category",
				axisLine: {
					show: false,
					lineStyle: {
						color: "#435459",
					},
				},
				axisTick: {
					show: false,
				},
				splitLine: {
					show: false,
				},
				axisLabel: {
					color: "#ffffff",
					fontSize: 10,
					interval: 0,
					padding: [0, 0, 0, 0],
				},
				data: ["农产品", "能源", "金属", "化工", "木材"],
			},
			{
				axisLine: {
					show: false,
					lineStyle: {
						color: "rgba(0,0,0,0)",
					},
				},
				data: [],
			},
		],
		yAxis: {
			type: "value",
			axisLine: {
				show: false,
			},
			axisTick: {
				show: false,
			},
			splitLine: {
				show: true,
				lineStyle: {
					type: [2, 2],
					dashOffset: 5,
					color: ["rgba(255, 255, 255, 1)"],
					opacity: 1,
					width: 0.3,
				},
			},
			axisLabel: {
				color: "#8B9EA4",
				fontSize: 9,
			},
		},
		series: [
			{
				name: "",
				data: [100, 120, 150, 110, 100],
				type: "bar",
				barWidth: 4,
				stack: "b",
				z: 3,
				yAxisIndex: 0,
				showBackground: false,
				backgroundStyle: {
					color: "rgba(180, 180, 180, 0.2)",
				},
				label: {
					show: true,
					position: "top",
					distance: 15,
					color: "#ffffff",
					fontSize: 10,
				},
				itemStyle: {
					borderRadius: 2,
					color: new graphic.LinearGradient(0, 0, 0, 1, [
						{ offset: 0, color: "#19FFC6" },
						{ offset: 1, color: "#33AAFF" },
					]),
				},
			},
			{
				type: "custom",
				renderItem: (_params, api) => {
					const categoryIndex = api.value(0);
					const categoryData = api.value(1);
					const basicsCoord = api.coord([categoryIndex, categoryData]);
					const topBasicsYAxis = basicsCoord[1];
					const basicsXAxis = basicsCoord[0];

					return {
						type: "image",
						style: {
							x: basicsXAxis - 4.5,
							y: topBasicsYAxis - 9,
							width: 10,
							height: 10,
							image:
								"data:image/png;base64,",
						},
					};
				},
				xAxisIndex: 1,
				data: [100, 120, 150, 110, 100],
			},
			{
				type: "bar",
				barWidth: 32,
				xAxisIndex: 1,
				barGap: "-220%",
				data: [150, 150, 150, 150, 150],
				emphasis: {
					focus: "none",
					itemStyle: { color: "rgba(255,255,255,0.8)" },
				},
				itemStyle: {
					color: "rgba(122,140,153,0.6)",
					opacity: 0.1,
				},
				z: 0,
			},
		],
	});

	// 初始化图表
	const initChart = () => {
		if (!chartRef) return;

		chartInstance = init(chartRef);
		chartInstance.setOption(option());

		// 自动调整大小
		const resizeObserver = new ResizeObserver(() => {
			chartInstance?.resize();
		});

		resizeObserver.observe(chartRef);

		return () => {
			resizeObserver.disconnect();
		};
	};

	// 清理图表实例
	const disposeChart = () => {
		if (chartInstance) {
			chartInstance.dispose();
			chartInstance = null;
		}
	};

	onMount(() => {
		const cleanupResize = initChart();

		onCleanup(() => {
			cleanupResize?.();
			disposeChart();
		});
	});

	// 如果需要响应式更新 option，使用 createEffect
	// createEffect(() => {
	//   chartInstance?.setOption(option(), true);
	// });

	return (
		<div
			id="left-card"
			class="tw:flex-1 tw:mb-3 tw:-translate-x-[150%] tw:opacity-0"
		>
			<Card title="大宗商品销售额">
				<div ref={chartRef} class="tw:size-full" />
			</Card>
		</div>
	);
}

